-- c013-v008: Iēsoûs Christós ayer y hoy el mismo y por los siglos
-- c013-v009: por–doctrinas diversas y extrañas no seáis-llevados bueno pues con–gracia ser-confirmado el corazón no con–comidas en las–cuales no fueron-beneficiados los que-andaban
-- c013-v010: Tenemos altar de el–cual comer no tienen derecho los en–el tabernáculo que-sirven
-- c013-v011: de–los–cuales pues es-llevada de–animales la sangre por pecado hacia los santos mediante el sumo-sacerdote de–estos los cuerpos son-quemados fuera del campamento
-- c013-v012: por-lo-cual también Iēsoûs para-que santificara mediante la propia sangre al pueblo fuera de–la puerta padeció
-- c013-v013: pues salgamos hacia él fuera del campamento el oprobio de–él llevando
-- c013-v014: no pues tenemos aquí permanente ciudad sino la venidera buscamos
-- c013-v015: mediante él pues ofrezcamos sacrificio de–alabanza a-través-de todo a Dios esto es fruto de–labios confesando el nombre de–él
-- c013-v016: de–la pero beneficencia y comunión no os-olvidéis con–tales pues sacrificios se-agrada el Dios
-- c013-v017: Obedeced a–los que-os-dirigen de–vosotros y someteos ellos pues velan por las almas de–vosotros como cuenta que-han-de-dar para-que con gozo esto hagan y no gimiendo no-provechoso pues para–vosotros esto
-- c013-v018: Orad por nosotros estamos-persuadidos pues que buena conciencia tenemos en todas-las-cosas bien queriendo conducirnos
-- c013-v019: más-abundantemente pero exhorto esto hacer para-que más-pronto os-sea-restituido a–vosotros
-- c013-v020: El pero Dios de–la paz el que-hizo-subir de muertos al pastor de–las ovejas el grande en sangre de–pacto eterno al Señor de–nosotros Iēsoûs
-- c013-v021: os-perfeccione a–vosotros en toda cosa-buena para el hacer la voluntad de–él haciendo en nosotros lo agradable delante-de él mediante Iēsoûs Christós a–quien la gloria por los siglos de–los siglos amēn
-- c013-v022: Exhorto pero a–vosotros hermanos soportad la palabra de–la exhortación y pues con breves-palabras os-he-escrito a–vosotros
-- c013-v023: Sabed al hermano de–nosotros Timótheos liberado con quien si más-pronto viene veré a–vosotros
